/**
 * Zentrale Datentypen für PulseBoard.
 * Die Datenstruktur ist versioniert, um Migrationen und das sichere
 * Laden von veralteten oder ungültigen gespeicherten Daten zu ermöglichen.
 */

export interface Activity {
  /** Universell eindeutige ID der Aktivität. */
  id: string
  /** Anzeigename. Muss nach Trimmen nicht leer sein. */
  name: string
  /** Optionale, ausführlichere Beschreibung. */
  description: string
  /** Kategorie zum Gruppieren (z. B. "Sport", "Arbeit"). */
  category: string
  /**
   * Tagesziel: wie oft die Aktivität pro Tag erreicht werden soll.
   * 0 bedeutet "kein Ziel" (ein einfacher Ein-/Aus-Schalter).
   */
  dailyTarget: number
  /** ISO-Timestamp des Anlegedatums. */
  createdAt: string
}

/**
 * Abgehakte Aktivitäten pro Kalendertag.
 * Key: Tag im Format YYYY-MM-DD (lokal).
 * Wert: Anzahl erledigter Einträge je Aktivitäts-ID für diesen Tag.
 */
export type Completions = Record<string, Record<string, number>>

/** Aktuelle, unterstützte Schema-Version. */
export const STORAGE_VERSION = 1

/** Schlüssel unter dem alle Daten im Storage abgelegt werden. */
export const STORAGE_KEY = 'pulseboard'

/** Vollständige, versionierte Datenstruktur. */
export interface StorageData {
  version: number
  activities: Record<string, Activity>
  completions: Completions
}

export interface NewActivityInput {
  name: string
  description?: string
  category: string
  dailyTarget?: number
}

export type ActivityInput = NewActivityInput

/**
 * Hilfsfunktionen für Datumsberechnungen.
 * Intern werden Datumsketten im Format YYYY-MM-DD (lokal) verwendet, damit
 * verschiedene Kalendertage sauber getrennt bleiben und es durch
 * Zeitzonen-/Sommerzeit-Umbuchungen keine Randfälle gibt.
 */

/** Liefert den aktuellen Tag als YYYY-MM-DD-Kette (lokal). */
export function todayKey(date: Date = new Date()): string {
  return dateToKey(date)
}

/** Wandelt ein lokales Date-Objekt in eine YYYY-MM-DD-Kette um. */
export function dateToKey(date: Date): string {
  const y = date.getFullYear()
  const m = String(date.getMonth() + 1).padStart(2, '0')
  const d = String(date.getDate()).padStart(2, '0')
  return `${y}-${m}-${d}`
}

/** Wandelt eine YYYY-MM-DD-Kette in ein lokales Date (Mitternacht) um. */
export function keyToDate(key: string): Date {
  const [y, m, d] = key.split('-').map(Number)
  // Monatsindex in JS ist 0-basiert.
  return new Date(y, m - 1, d)
}

/** Addiert (oder subtrahiert) ganze Tage zu einer Kette. vermeidet DST-Sprünge. */
export function addDays(key: string, days: number): string {
  const date = keyToDate(key)
  date.setDate(date.getDate() + days)
  return dateToKey(date)
}

/** Ist der Tag strictly nach dem heutigen Tag? */
export function isFuture(key: string, today: string = todayKey()): boolean {
  return key > today
}

/** Ist der Tag der heutige? */
export function isToday(key: string, today: string = todayKey()): boolean {
  return key === today
}

/**
 * Menschlich lesbares Label für einen Tag relativ zu "heute".
 * Nutzt Intl.DateTimeFormat für eine saubere, lokale Formatierung.
 */
export function formatDayLabel(key: string, today: string = todayKey()): string {
  const date = keyToDate(key)
  const opts: Intl.DateTimeFormatOptions = {
    weekday: 'long',
    day: 'numeric',
    month: 'long',
  }

  if (isToday(key, today)) {
    return 'Heute'
  }

  const yesterday = addDays(today, -1)
  const tomorrow = addDays(today, 1)
  if (key === yesterday) return 'Gestern'
  if (key === tomorrow) return 'Morgen'

  return new Intl.DateTimeFormat('de-DE', opts).format(date)
}

/** Saubere, kurze Formatierung z. B. für die Navigationsleiste. */
export function formatShort(key: string): string {
  const date = keyToDate(key)
  return new Intl.DateTimeFormat('de-DE', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
  }).format(date)
}

/**
 * Persistenzschicht für PulseBoard.
 *
 * Verantwortlichkeiten:
 * - Lesen/Schreiben einer versionierten Datenstruktur in einem Storage-Backend
 *   (Standard: localStorage).
 * - Migration von älteren Schema-Versionen (aktuell v0 -> v1).
 * - Robustheit: ungültige, veraltete oder beschädigte Daten dürfen nie zum
 *   Absturz führen. Stattdessen wird sicher ein leerer Ausgangszustand
 *   verwendet.
 */

import type { Activity, Completions, NewActivityInput, StorageData } from '../types'
import { STORAGE_KEY, STORAGE_VERSION } from '../types'

/** Minimaler Storage-Contract, um Tests mit einem In-Memory-Backend zu ermöglichen. */
export interface StorageBackend {
  get(key: string): string | null
  set(key: string, value: string): void
  remove(key: string): void
}

export const defaultBackend: StorageBackend = {
  get: (key) => localStorage.getItem(key),
  set: (key, value) => localStorage.setItem(key, value),
  remove: (key) => localStorage.removeItem(key),
}

/** Erstellt einen sauberen, leeren Ausgangszustand der aktuellen Version. */
export function createEmptyData(): StorageData {
  return { version: STORAGE_VERSION, activities: {}, completions: {} }
}

// ---------------------------------------------------------------------------
// Validierung & Migration
// ---------------------------------------------------------------------------

function isValidActivity(value: unknown): value is Activity {
  if (typeof value !== 'object' || value === null) {
    return false
  }
  const a = value as Record<string, unknown>
  return (
    typeof a.id === 'string' &&
    typeof a.name === 'string' &&
    typeof a.description === 'string' &&
    typeof a.category === 'string' &&
    typeof a.dailyTarget === 'number' &&
    Number.isFinite(a.dailyTarget) &&
    typeof a.createdAt === 'string'
  )
}

function normalizeActivities(value: unknown): Record<string, Activity> {
  const result: Record<string, Activity> = {}
  if (value == null) {
    return result
  }
  const entries = Array.isArray(value) ? value : Object.values(value as object)
  for (const entry of entries) {
    if (isValidActivity(entry)) {
      // Sicherheit: Tagesziel nie negativ.
      entry.dailyTarget = Math.max(0, entry.dailyTarget)
      result[entry.id] = entry
    }
  }
  return result
}

function normalizeCompletions(value: unknown): Completions {
  const result: Completions = {}
  if (value == null || typeof value !== 'object' || Array.isArray(value)) {
    return result
  }
  for (const [date, perDay] of Object.entries(value as Record<string, unknown>)) {
    if (typeof perDay !== 'object' || perDay == null || Array.isArray(perDay)) {
      continue
    }
    const counts: Record<string, number> = {}
    for (const [activityId, count] of Object.entries(perDay as Record<string, unknown>)) {
      if (typeof count === 'number' && Number.isFinite(count) && count > 0) {
        counts[activityId] = Math.floor(count)
      }
    }
    if (Object.keys(counts).length > 0) {
      result[date] = counts
    }
  }
  return result
}

/**
 * Konvertiert eine v0-Datenstruktur (Array-basiert) in das v1-Objekt-Format.
 * Gibt `null` zurück, wenn die Grundstruktur nicht verwendbar ist.
 */
function migrateV0(parsed: Record<string, unknown>): StorageData | null {
  const activities = normalizeActivities(parsed.activities)
  const completions = normalizeCompletions(parsed.completions)
  return { version: STORAGE_VERSION, activities, completions }
}

/**
 * Validiert und migriert einen geparsten Wert.
 * Gibt `null` zurück, wenn die Struktur grundsätzlich unhambarrlich ist
 * (z. B. Zahl, String, Array auf Top-Ebene, unbekannte Version).
 */
export function parseStored(raw: string | null): StorageData | null {
  if (!raw) {
    return createEmptyData()
  }

  let parsed: unknown
  try {
    parsed = JSON.parse(raw)
  } catch {
    // Beschädigtes JSON -> sicher leer, kein Absturz.
    return null
  }

  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    return null
  }

  const record = parsed as Record<string, unknown>
  const version = typeof record.version === 'number' ? record.version : STORAGE_VERSION

  if (version === STORAGE_VERSION) {
    const activities = normalizeActivities(record.activities)
    const completions = normalizeCompletions(record.completions)
    return { version: STORAGE_VERSION, activities, completions }
  }

  if (version === 0) {
    return migrateV0(record)
  }

  // Unbekannte/zukünftige Version -> zurücksetzen, aber nicht abstürzen.
  return null
}

// ---------------------------------------------------------------------------
// Lese-/Schreiboperationen
// ---------------------------------------------------------------------------

/** Liest und normalisiert die gespeicherten Daten aus dem Backend. */
export function readStored(backend: StorageBackend = defaultBackend): StorageData {
  const parsed = parseStored(backend.getItem(STORAGE_KEY))
  return parsed ?? createEmptyData()
}

/** Schreibt die Daten serialisiert ins Backend und fängt Fehler ab. */
export function writeStored(data: StorageData, backend: StorageBackend = defaultBackend): void {
  try {
    backend.set(STORAGE_KEY, JSON.stringify(data))
  } catch {
    // Z. B. Speicherlimit oder gesperrter Storage: nicht kritisch für die App.
  }
}

export function clearStored(backend: StorageBackend = defaultBackend): void {
  try {
    backend.remove(STORAGE_KEY)
  } catch {
    // ignore
  }
}

// ---------------------------------------------------------------------------
// Validierung von Aktivitäts-Eingaben
// ---------------------------------------------------------------------------

export interface ValidatedActivity {
  ok: true
  activity: Activity
}

export interface InvalidActivity {
  ok: false
  error: string
}

export type ValidationResult = ValidatedActivity | InvalidActivity

/**
 * Prüft und normalisiert eine Aktivitäts-Eingabe.
 * Gibt eine Fehlermeldung zurück, wenn die Eingabe ungült ist.
 */
export function validateActivity(
  input: NewActivityInput,
  overrides: Partial<Activity>,
): ValidationResult {
  const name = (input.name ?? '').trim()
  const category = (input.category ?? '').trim()
  const description = (input.description ?? '').trim()

  let dailyTarget = 0
  if (input.dailyTarget !== undefined && input.dailyTarget !== null) {
    const value = Number(input.dailyTarget)
    if (Number.isFinite(value) && value >= 0) {
      dailyTarget = Math.floor(value)
    } else {
      return { ok: false, error: 'Tagesziel muss eine Zahl größer oder gleich 0 sein.' }
    }
  }

  if (name.length === 0) {
    return { ok: false, error: 'Bitte gib einen Name ein.' }
  }
  if (category.length === 0) {
    return { ok: false, error: 'Bitte wähle eine Kategorie aus.' }
  }

  return {
    ok: true,
    activity: {
      id: overrides.id ?? crypto.randomUUID(),
      name,
      description,
      category,
      dailyTarget,
      createdAt: overrides.createdAt ?? new Date().toISOString(),
    },
  }
}

/**
 * Reiner Speicher/Logik-Fabrik für PulseBoard (ohne React).
 *
 * Die Fabrik hält den Zustand im Speicher, schreibt nach jeder Änderung persist
 * ins Backend und benachrichtigt Subscriber. Dadurch lässt sich die gesamte
 * Geschäftslogik (Erstellen/Bearbeiten/Löschen, Tagesstatus, Datumswechsel,
 * Persistenz, umgehen mit beschädigten Daten) ohne Framework testen.
 */

import { addDays, isFuture, todayKey } from '../lib/date'
import {
  clearStored,
  readStored,
  StorageBackend,
  defaultBackend,
  validateActivity,
  writeStored,
} from '../lib/storage'
import type { Activity, ActivityInput, Completions, NewActivityInput, StorageData } from '../types'
import { STORAGE_KEY } from '../types'

export interface AppState {
  data: StorageData
  selectedDate: string
}

export interface Store {
  getState(): AppState
  subscribe(listener: () => void): () => void
  setSelectedDate(date: string): void
  addActivity(input: NewActivityInput): Activity | null
  editActivity(id: string, input: ActivityInput): boolean
  deleteActivity(id: string): void
  toggleComplete(activityId: string, date: string): void
  reload(): void
  reset(): void
}

export interface StoreFactoryOptions {
  backend?: StorageBackend
  now?: () => Date
}

interface Internal {
  state: AppState
  backend: StorageBackend
  now: () => Date
  listeners: Set<() => void>
}

function computeNow(internal: Internal): string {
  return todayKey(internal.now())
}

function persist(internal: Internal): void {
  writeStored(internal.state.data, internal.backend)
}

function emit(internal: Internal): void {
  for (const listener of internal.listeners) {
    listener()
  }
}

export function createStore(options: StoreFactoryOptions = {}): Store {
  const backend = options.backend ?? defaultBackend
  const now = options.now ?? (() => new Date())
  const internal: Internal = {
    state: { data: readStored(backend), selectedDate: computeNow(internal) },
    backend,
    now,
    listeners: new Set(),
  }

  function setState(next: Partial<AppState>): void {
    internal.state = { ...internal.state, ...next }
    persist(internal)
    emit(internal)
  }

  return {
    getState() {
      return internal.state
    },

    subscribe(listener) {
      internal.listeners.add(listener)
      return () => {
        internal.listeners.delete(listener)
      }
    },

    setSelectedDate(date) {
      setState({ selectedDate: date })
    },

    addActivity(input) {
      const result = validateActivity(input, {})
      if (!result.ok) {
        return null
      }
      const activity = result.activity
      internal.state.data.activities[activity.id] = activity
      persist(internal)
      emit(internal)
      return activity
    },

    editActivity(id, input) {
      const existing = internal.state.data.activities[id]
      if (!existing) {
        return false
      }
      const result = validateActivity(input, { id, createdAt: existing.createdAt })
      if (!result.ok) {
        return false
      }
      internal.state.data.activities[id] = result.activity
      persist(internal)
      emit(internal)
      return true
    },

    deleteActivity(id) {
      if (!internal.state.data.activities[id]) {
        return
      }
      delete internal.state.data.activities[id]
      // Verwaigte Zählstände entfernen.
      for (const dateKeys of Object.values(internal.state.data.completions)) {
        delete dateKeys[id]
      }
      persist(internal)
      emit(internal)
    },

    toggleComplete(activityId, date) {
      const activity = internal.state.data.activities[activityId]
      if (!activity) {
        return
      }
      // Zukünftige Tage dürfen nicht als erledigt markiert werden.
      if (isFuture(date, computeNow(internal))) {
        return
      }
      const target = Math.max(0, activity.dailyTarget)
      const current = internal.state.data.completions[date]?.[activityId] ?? 0

      let next: number
      if (target > 0) {
        next = current < target ? current + 1 : current - 1
      } else {
        next = current > 0 ? 0 : 1
      }

      const dayCompletions = internal.state.data.completions[date] ?? {}
      if (next <= 0) {
        delete dayCompletions[activityId]
        if (Object.keys(dayCompletions).length === 0) {
          delete internal.state.data.completions[date]
        }
      } else {
        dayCompletions[activityId] = next
        internal.state.data.completions[date] = dayCompletions
      }
      persist(internal)
      emit(internal)
    },

    reload() {
      internal.state = { data: readStored(internal.backend), selectedDate: computeNow(internal) }
      persist(internal)
      emit(internal)
    },

    reset() {
      clearStored(internal.backend)
      internal.state = { data: readStored(internal.backend), selectedDate: computeNow(internal) }
      emit(internal)
    },
  }
}

// ---------------------------------------------------------------------------
// Hilfsfunktionen für die Ansicht
// ---------------------------------------------------------------------------

/** Anzahl erledigter Einträge einer Aktivität an einem Tag. */
export function getCompletedCount(
  data: StorageData,
  activityId: string,
  date: string,
): number {
  return data.completions[date]?.[activityId] ?? 0
}

/** Ist eine Aktivität an einem Tag als (voll) erledigt? */
export function isCompleted(data: StorageData, activity: Activity, date: string): boolean {
  const count = getCompletedCount(data, activity.id, date)
  if (activity.dailyTarget > 0) {
    return count >= activity.dailyTarget
  }
  return count > 0
}

export interface CategoryStat {
  name: string
  total: number
  completed: number
}

export interface DayStats {
  total: number
  completed: number
  open: number
  percent: number
  byCategory: CategoryStat[]
}

/** Berechnet die Dashboard-Statistik für einen Tag. */
export function computeStats(data: StorageData, date: string): DayStats {
  const activities = Object.values(data.activities)
  const total = activities.length
  let completed = 0
  const byCategoryMap = new Map<string, { total: number; completed: number }>()

  for (const activity of activities) {
    const done = isCompleted(data, activity, date)
    if (done) {
      completed += 1
    }
    const cat = activity.category || 'Ohne Kategorie'
    const entry = byCategoryMap.get(cat) ?? { total: 0, completed: 0 }
    entry.total += 1
    if (done) {
      entry.completed += 1
    }
    byCategoryMap.set(cat, entry)
  }

  const byCategory = [...byCategoryMap.entries()]
    .map(([name, values]) => ({ name, ...values }))
    .sort((a, b) => a.name.localeCompare(b.name))

  const open = total - completed
  const percent = total === 0 ? 0 : Math.round((completed / total) * 100)

  return { total, completed, open, percent, byCategory }
}

/** Liefert sortierte, eindeutige Kategorien aus den aktuellen Aktivitäten. */
export function listCategories(data: StorageData): string[] {
  const categories = new Set<string>()
  for (const activity of Object.values(data.activities)) {
    if (activity.category) {
      categories.add(activity.category)
    }
  }
  return [...categories].sort((a, b) => a.localeCompare(b))
}

export { addDays, todayKey }

import { useEffect, useMemo, useState } from 'react'
import { createStore, type Store } from '../store/createStore'
import type { ActivityInput, NewActivityInput } from '../types'
import type { AppState } from '../store/createStore'

export interface AppActions {
  setSelectedDate: (date: string) => void
  addActivity: (input: NewActivityInput) => Activity | null
  editActivity: (id: string, input: ActivityInput) => boolean
  deleteActivity: (id: string) => void
  toggleComplete: (activityId: string, date: string) => void
  reload: () => void
  reset: () => void
}

/**
 * React-Wrapper um die reine Speicherfabrik. Haltet den Zustand synchron und
 * schreibt Änderungen persist in den Storage.
 */
export function useAppStore(): AppState & AppActions {
  const store = useMemo<Store>(() => createStore(), [])

  const [state, setState] = useState<AppState>(() => store.getState())

  useEffect(() => {
    return store.subscribe(() => setState(store.getState()))
  }, [store])

  const actions = useMemo<AppActions>(
    () => ({
      setSelectedDate: (date) => store.setSelectedDate(date),
      addActivity: (input) => store.addActivity(input),
      editActivity: (id, input) => store.editActivity(id, input),
      deleteActivity: (id) => store.deleteActivity(id),
      toggleComplete: (activityId, date) => store.toggleComplete(activityId, date),
      reload: () => store.reload(),
      reset: () => store.reset(),
    }),
    [store],
  )

  return { ...state, ...actions }
}

import { useEffect, useState } from 'react'

export type ThemeChoice = 'system' | 'light' | 'dark'

const THEME_KEY = 'pulseboard-theme'

function getInitialChoice(): ThemeChoice {
  try {
    const stored = localStorage.getItem(THEME_KEY)
    if (stored === 'light' || stored === 'dark' || stored === 'system') {
      return stored
    }
  } catch {
    // ignore
  }
  return 'system'
}

function resolveTheme(choice: ThemeChoice): 'light' | 'dark' {
  if (choice === 'light') return 'light'
  if (choice === 'dark') return 'dark'
  const prefersDark =
    typeof window !== 'undefined' &&
    window.matchMedia &&
    window.matchMedia('(prefers-color-scheme: dark)').matches
  return prefersDark ? 'dark' : 'light'
}

function applyTheme(theme: 'light' | 'dark'): void {
  const root = document.documentElement
  root.setAttribute('data-theme', theme)
  const meta = document.querySelector<metaElement>('meta[name="theme-color"]')
  if (meta) {
    meta.content = theme === 'dark' ? '#0f172a' : '#f8fafc'
  }
}

interface metaElement extends HTMLMetaElement {}

/**
 * Verwählt und synchronisiert den Dark/Light-Modus. Standard ist das System-
 * Präferenz, die Wahl wird lokal gespeichert.
 */
export function useTheme(): { choice: ThemeChoice; setChoice: (c: ThemeChoice) => void } {
  const [choice, setChoice] = useState<ThemeChoice>(getInitialChoice)

  useEffect(() => {
    const theme = resolveTheme(choice)
    applyTheme(theme)
    try {
      localStorage.setItem(THEME_KEY, choice)
    } catch {
      // ignore
    }
  }, [choice])

  return { choice, setChoice }
}

