import { useTheme } from '../hooks/useTheme'
import { MoonIcon, SunIcon } from './icons'

/** Umschalter zwischen Light-/Dark-Modus (klickbar, keyboard-freundlich). */
export function ThemeToggle() {
  const { choice, setChoice } = useTheme()
  const isDark = choice === 'dark' || (choice === 'system' && darkModeMatches())

  return (
    <button
      type="button"
      className="icon-btn"
      onClick={() => setChoice(isDark ? 'light' : 'dark')}
      aria-label={isDark ? 'Hellen Modus wählen' : 'Dunkelen Modus wählen'}
      aria-pressed={isDark}
      title={choice === 'system' ? 'System' : choice}
    >
      {isDark ? <MoonIcon /> : <SunIcon />}
    </button>
  )
}

function darkModeMatches(): boolean {
  if (typeof window === 'undefined' || !window.matchMedia) return false
  return window.matchMedia('(prefers-color-scheme: dark)').matches
}

import { useNotifications } from '../hooks/useNotifications'

/** Zeigt kurzlebige Feedback-Meldungen (Toast) an. */
export function Notifications() {
  const { notifications, dismiss } = useNotifications()

  if (notifications.length === 0) {
    return null
  }

  return (
    <div className="toasts" role="status" aria-live="polite">
      {notifications.map((n) => (
        <button
          key={n.id}
          type="button"
          className={`toast toast--${n.type}`}
          onClick={() => dismiss(n.id)}
          aria-label="Meldung schließen"
        >
          <span className="toast__message">{n.message}</span>
          <span className="toast__close" aria-hidden="true">
            ×
          </span>
        </button>
      ))}
    </div>
  )
}

import type { DayStats } from '../store/createStore'
import { SparkleIcon } from './icons'

interface DashboardProps {
  stats: DayStats
}

/** Fortschrittsbalken. */
function ProgressBar({ percent }: { percent: number }) {
  return (
    <div className="progress" role="progressbar" aria-valuenow={percent} aria-valuemin={0} aria-valuemax={100} aria-label="Tagesfortschritt">
      <div className="progress__track">
        <div className="progress__fill" style={{ width: `${percent}%` }} />
      </div>
      <span className="progress__value">{percent}%</span>
    </div>
  )
}

/** Übersicht nach Kategorie. */
function CategoryOverview({ byCategory }: { byCategory: DayStats['byCategory'] }) {
  if (byCategory.length === 0) {
    return null
  }
  return (
    <div className="categories">
      <h2 className="categories__title">Kategorien</h2>
      <ul className="categories__list">
        {byCategory.map((c) => {
          const catPercent = c.total === 0 ? 0 : Math.round((c.completed / c.total) * 100)
          return (
            <li key={c.name} className="category">
              <div className="category__top">
                <span className="category__name">{c.name}</span>
                <span className="category__count">
                  {c.completed}/{c.total}
                </span>
              </div>
              <div className="progress progress--sm">
                <div className="progress__track">
                  <div className="progress__fill" style={{ width: `${catPercent}%` }} />
                </div>
                <span className="progress__value progress__value--sm">{catPercent}%</span>
              </div>
            </li>
          )
        })}
      </ul>
    </div>
  )
}

/** Dashboard: erledigt/offen/Prozent + Kategorie-Übersicht. */
export function Dashboard({ stats }: DashboardProps) {
  const { completed, open, percent } = stats

  return (
    <section className="dashboard" aria-label="Tagesübersicht">
      <div className="dashboard__stats">
        <Stat icon={<SparkleIcon />} label="Erledigt" value={completed} highlight />
        <Stat icon={<SparkleIcon />} label="Offen" value={open} />
        <Stat icon={<SparkleIcon />} label="Gesamt" value={stats.total} />
      </div>

      <ProgressBar percent={percent} />

      <CategoryOverview byCategory={stats.byCategory} />
    </section>
  )
}

function Stat({
  icon,
  label,
  value,
  highlight,
}: {
  icon: React.ReactNode
  label: string
  value: number
  highlight?: boolean
}) {
  return (
    <div className="stat" aria-label={label}>
      <div className="stat__icon" aria-hidden="true">
        {icon}
      </div>
      <div className="stat__value" data-highlight={Boolean(highlight)}>
        {value}
      </div>
      <div className="stat__label">{label}</div>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { useNotifications } from '../hooks/useNotifications'
import { validateActivity } from '../lib/storage'
import type { Activity, ActivityInput } from '../types'
import { EditIcon, PlusIcon, TrashIcon } from './icons'

export type FormMode = 'create' | 'edit'

interface ActivityFormProps {
  mode: FormMode
  initial?: Activity
  categories: string[]
  onSubmit: (input: ActivityInput) => void
  onCancel: () => void
  onDelete?: () => void
}

interface FieldState {
  name: string
  description: string
  category: string
  dailyTarget: string // als Text, um leere Eingänge zu erlauben
}

const EMPTY: FieldState = { name: '', description: '', category: '', dailyTarget: '' }

/** Formular zum Erstellen und Bearbeiten von Aktivitäten. */
export function ActivityForm({
  mode,
  initial,
  categories,
  onSubmit,
  onCancel,
  onDelete,
}: ActivityFormProps) {
  const { notify } = useNotifications()
  const [fields, setFields] = useState<FieldState>(EMPTY)
  const [error, setError] = useState<string>('')

  useEffect(() => {
    if (mode === 'edit' && initial) {
      setFields({
        name: initial.name,
        description: initial.description,
        category: initial.category,
        dailyTarget: initial.dailyTarget > 0 ? String(initial.dailyTarget) : '',
      })
      setError('')
    } else {
      setFields(EMPTY)
      setError('')
    }
  }, [mode, initial])

  function set<K extends keyof FieldState>(key: K, value: FieldState[K]) {
    setFields((f) => ({ ...f, [key]: value }))
    if (error) setError('')
  }

  function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const input: ActivityInput = {
      name: fields.name,
      description: fields.description,
      category: fields.category,
      dailyTarget: fields.dailyTarget === '' ? undefined : Number(fields.dailyTarget),
    }
    const result = validateActivity(input, mode === 'edit' ? { id: initial?.id } : {})
    if (!result.ok) {
      setError(result.error)
      notify(result.error, 'error')
      return
    }
    onSubmit(input)
  }

  const isEdit = mode === 'edit'

  return (
    <form className="activity-form" onSubmit={handleSubmit} noValidate>
      <div className="activity-form__row">
        <label className="field">
          <span className="field__label">Name</span>
          <input
            type="text"
            value={fields.name}
            autoComplete="off"
            onChange={(e) => set('name', e.target.value)}
            aria-required="true"
            aria-invalid={error ? 'true' : undefined}
            aria-describedby={error ? 'activity-form-error' : undefined}
            placeholder="z. B. Sport, Lesen, Wasser trinken"
          />
        </label>

        <label className="field">
          <span className="field__label">Kategorie</span>
          <input
            type="text"
            list="categories"
            value={fields.category}
            onChange={(e) => set('category', e.target.value)}
            aria-required="true"
            aria-invalid={error ? 'true' : undefined}
            placeholder="z. B. Gesundheit"
          />
        </label>
      </div>

      <label className="field">
        <span className="field__label">Beschreibung <span className="field__optional">(optional)</span></span>
        <input
          type="text"
          value={fields.description}
          autoComplete="off"
          onChange={(e) => set('description', e.target.value)}
          placeholder="Was oder warum?"
        />
      </label>

      <div className="activity-form__row">
        <label className="field">
          <span className="field__label">Tagesziel <span className="field__optional">(optional)</span></span>
          <input
            type="number"
            inputMode="numeric"
            min="0"
            step="1"
            value={fields.dailyTarget}
            onChange={(e) => set('dailyTarget', e.target.value)}
            placeholder="0 = kein Ziel"
          />
        </label>

        <div className="activity-form__actions">
          <button type="button" className="btn btn--ghost" onClick={onCancel}>
            {isEdit ? 'Abbrechen' : 'Abbrechen'}
          </button>
          <button type="submit" className="btn btn--primary">
            {isEdit ? <EditIcon /> : <PlusIcon />}
            {isEdit ? 'Speichern' : 'Hinzufügen'}
          </button>
        </div>
      </div>

      {isEdit && onDelete && (
        <button type="button" className="btn btn--danger" onClick={onDelete}>
          <TrashIcon />
          Löschen
        </button>
      )}

      {error && (
        <p className="activity-form__error" id="activity-form-error" role="alert">
          {error}
        </p>
      )}

      <datalist id="categories">
        {categories.map((c) => (
          <option key={c} value={c} />
        ))}
      </datalist>
    </form>
  )
}

import type { Activity } from '../types'
import { CheckIcon, EditIcon } from './icons'

interface ActivityItemProps {
  activity: Activity
  completedCount: number
  isCompleted: boolean
  isFuture: boolean
  onToggle: () => void
  onEdit: () => void
  onDelete: () => void
}

/** Eine einzelne Aktivitätszeile mit Zähler und Aktionsknöpfen. */
export function ActivityItem({
  activity,
  completedCount,
  isCompleted,
  isFuture,
  onToggle,
  onEdit,
  onDelete,
}: ActivityItemProps) {
  const target = activity.dailyTarget > 0 ? activity.dailyTarget : null

  const statusText = isFuture
    ? 'Zukünftiger Tag'
    : target
      ? `${completedCount} / ${target}`
      : completedCount > 0
        ? 'Erledigt'
        : 'Offen'

  return (
    <li className="activity" data-completed={isCompleted || undefined}>
      <button
        type="button"
        className={`activity__check${isCompleted ? ' is-done' : ''}`}
        onClick={onToggle}
        disabled={isFuture}
        aria-pressed={isCompleted}
        aria-label={`"${activity.name}" für ${statusText} umsetzen`}
        title={statusText}
      >
        {isCompleted && <CheckIcon />}
      </button>

      <div className="activity__main" onClick={onEdit} style={{ cursor: 'pointer' }}>
        <div className="activity__name" aria-hidden="true">
          {activity.name}
        </div>
        <div className="activity__meta">
          <span className="badge">{activity.category}</span>
          {activity.description && <span className="activity__desc">{activity.description}</span>}
        </div>
      </div>

      <div className="activity__counter" aria-hidden="true">
        {target ? (
          <span className="activity__target">
            {completedCount}/{target}
          </span>
        ) : null}
      </div>

      <div className="activity__actions">
        <button
          type="button"
          className="icon-btn"
          onClick={onEdit}
          aria-label={`"${activity.name}" bearbeiten`}
          title="Bearbeiten"
        >
          <EditIcon />
        </button>
        <button
          type="button"
          className="icon-btn icon-btn--danger"
          onClick={onDelete}
          aria-label={`"${activity.name}" löschen`}
          title="Löschen"
        >
          <span aria-hidden="true">✕</span>
        </button>
      </div>
    </li>
  )
}

