          isCompleted={isCompleted(data, activity, date)}
          isFuture={date > todayKey()}
          onToggle={() => onToggle(activity.id)}
          onEdit={() => onEdit(activity.id)}
          onDelete={() => onDelete(activity.id)}
        />
      ))}
    </ul>
  )
}

