/* ---------------------------------------------------------------------------
 * PulseBoard — Styles
 * Sauberes, ruhiges Design mit system-basiertem Dark Mode.
 *---------------------------------------------------------------------------- */

:root {
  --bg: #f8fafc;
  --bg-elevated: #ffffff;
  --surface: #ffffff;
  --surface-alt: #f1f5f9;
  --border: #e2e8f0;
  --border-strong: #cbd5e1;

  --text: #0f172a;
  --text-muted: #64748b;
  --text-on-accent: #ffffff;

  --primary: #4f46e5;
  --primary-hover: #4338ca;
  --primary-weak: #eef2ff;

  --danger: #dc2626;
  --danger-hover: #b91c1c;
  --danger-weak: #fef2f2;

  --success: #059669;
  --success-weak: #ecfdf5;

  --warning: #d97706;

  --shadow-sm: 0 1px 2px rgba(15, 23, 42, 0.06);
  --shadow-md: 0 6px 20px rgba(15, 23, 42, 0.08);

  --radius-sm: 8px;
  --radius: 14px;
  --radius-lg: 20px;

  --focus: #6366f1;

  --font: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial,
    sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji';
}

[data-theme='dark'] {
  --bg: #0b1120;
  --bg-elevated: #0f172a;
  --surface: #1e293b;
  --surface-alt: #273449;
  --border: #2d3a52;
  --border-strong: #3f5170;

  --text: #e2e8f0;
  --text-muted: #94a3b8;
  --text-on-accent: #ffffff;

  --primary: #818cf8;
  --primary-hover: #a5b4fc;
  --primary-weak: #1e2444;

  --danger: #f87171;
  --danger-hover: #fca5a5;
  --danger-weak: #3b1c1c;

  --success: #34d399;
  --success-weak: #10332a;

  --warning: #fbbf24;

  --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.4);
  --shadow-md: 0 8px 24px rgba(0, 0, 0, 0.45);
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 16px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

h1,
h2,
h3 {
  margin: 0;
  font-weight: 650;
  letter-spacing: -0.01em;
}

button {
  font-family: inherit;
}

/* ---------------------------------------------------------------------------
 * Layout
 *---------------------------------------------------------------------------- */

.app {
  min-height: 100vh;
  display: flex;
  justify-content: center;
  padding: 24px 16px calc(24px + env(safe-area-inset-bottom));
}

.app__inner {
  width: 100%;
  max-width: 640px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* ---------------------------------------------------------------------------
 * Header
 *---------------------------------------------------------------------------- */

.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 4px 4px 0;
}

.header__brand {
  display: flex;
  align-items: center;
  gap: 12px;
}

.header__logo {
  width: 44px;
  height: 44px;
  border-radius: 14px;
  background: linear-gradient(135deg, var(--primary), #7c3aed);
  display: grid;
  place-items: center;
  box-shadow: var(--shadow-md);
}

.header__dot {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--bg-elevated);
  box-shadow: 0 0 0 4px rgba(255, 255, 255, 0.25);
}

.header__title {
  font-size: 20px;
}

.header__subtitle {
  margin: 0;
  color: var(--text-muted);
  font-size: 13px;
}

/* ---------------------------------------------------------------------------
 * Buttons
 *---------------------------------------------------------------------------- */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  padding: 10px 16px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.12s ease, border-color 0.12s ease,
    color 0.12s ease, transform 0.04s ease;
  line-height: 1;
}

.btn:active {
  transform: translateY(1px);
}

.btn--primary {
  background: var(--primary);
  color: var(--text-on-accent);
}

.btn--primary:hover {
  background: var(--primary-hover);
}

.btn--ghost {
  background: transparent;
  color: var(--text-muted);
  border-color: var(--border);
}

.btn--ghost:hover {
  background: var(--surface-alt);
  color: var(--text);
}

.btn--danger {
  background: var(--danger-weak);
  color: var(--danger);
  border-color: var(--border);
}

.btn--danger:hover {
  background: var(--danger);
  color: #fff;
}

.icon-btn {
  display: inline-grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--surface);
  color: var(--text-muted);
  cursor: pointer;
  transition: background-color 0.12s ease, color 0.12s ease, border-color 0.12s ease;
}

.icon-btn:hover {
  background: var(--surface-alt);
  color: var(--text);
}

.icon-btn--danger:hover {
  background: var(--danger-weak);
  color: var(--danger);
}

/* ---------------------------------------------------------------------------
 * Focus visibility (keyboard users)
 *---------------------------------------------------------------------------- */

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 6px;
}

:focus:not(:focus-visible) {
  outline: none;
}

/* ---------------------------------------------------------------------------
 * Day navigation
 *---------------------------------------------------------------------------- */

.day-nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 12px;
  box-shadow: var(--shadow-sm);
}

.day-nav__center {
  text-align: center;
  flex: 1;
}

.day-nav__label {
  font-size: 17px;
  font-weight: 650;
}

.day-nav__sub {
  font-size: 12px;
  color: var(--text-muted);
  margin-top: 2px;
}

.day-nav__btn {
  display: inline-grid;
  place-items: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border);
  background: var(--surface);
  color: var(--text);
  cursor: pointer;
  transition: background-color 0.12s ease, color 0.12s ease;
}

.day-nav__btn:hover {
  background: var(--surface-alt);
}

.day-nav__btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.day-nav__today {
  border: none;
  background: transparent;
  color: var(--primary);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  white-space: nowrap;
}

.day-nav__today:hover {
  background: var(--primary-weak);
}

.day-nav__today.is-active {
  background: var(--primary-weak);
  color: var(--primary-hover);
}

/* ---------------------------------------------------------------------------
 * Dashboard
 *---------------------------------------------------------------------------- */

.dashboard {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.dashboard__stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.stat {
  text-align: center;
  padding: 12px 8px;
  background: var(--surface-alt);
  border-radius: var(--radius-sm);
}

.stat__icon {
  display: inline-grid;
  place-items: center;
  color: var(--primary);
  width: 28px;
  height: 28px;
  margin-bottom: 6px;
}

.stat__value {
  font-size: 26px;
  font-weight: 700;
  line-height: 1.1;
}

.stat__value[data-highlight='true'] {
  color: var(--primary);
}

.stat__label {
  font-size: 12px;
  color: var(--text-muted);
  margin-top: 2px;
}

/* Progress bar */
.progress {
  display: flex;
  align-items: center;
  gap: 12px;
}

.progress--sm {
  margin-top: 8px;
  gap: 8px;
}

.progress__track {
  flex: 1;
  height: 10px;
  background: var(--surface-alt);
  border-radius: 999px;
  overflow: hidden;
}

.progress__fill {
  height: 100%;
  background: linear-gradient(90deg, var(--primary), #7c3aed);
  border-radius: 999px;
  transition: width 0.3s ease;
}

.progress__value {
  font-size: 13px;
  font-weight: 650;
  color: var(--text-muted);
  min-width: 40px;
  text-align: right;
}

.progress__value--sm {
  min-width: 34px;
  font-size: 11px;
}

/* Categories */
.categories {
  border-top: 1px solid var(--border);
  padding-top: 16px;
}

.categories__title {
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-muted);
  margin-bottom: 10px;
}

.categories__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.category__top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 6px;
}

.category__name {
  font-weight: 600;
  font-size: 14px;
}

.category__count {
  font-size: 13px;
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
}

/* ---------------------------------------------------------------------------
 * Add panel
 *---------------------------------------------------------------------------- */

.add-panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
}

.add-panel__summary {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 14px 16px;
  font-weight: 600;
  color: var(--primary);
  cursor: pointer;
  list-style: none;
  font-size: 15px;
}

.add-panel__summary::-webkit-details-marker {
  display: none;
}

.add-panel__summary::before {
  content: '+';
  display: inline-grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border-radius: 6px;
  background: var(--primary-weak);
  color: var(--primary);
  font-size: 16px;
  line-height: 1;
}

.add-panel[open] .add-panel__summary::before {
  content: '–';
}

/* ---------------------------------------------------------------------------
 * Forms
 *---------------------------------------------------------------------------- */

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 13px;
  color: var(--text-muted);
}

.field__optional {
  font-weight: 400;
  opacity: 0.7;
}

.activity-form {
  padding: 4px 16px 16px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.activity-form__row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.activity-form__actions {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
}

.activity-form input {
  width: 100%;
}

input {
  font-size: 15px;
  padding: 10px 12px;
  border: 1px solid var(--border-strong);
  border-radius: var(--radius-sm);
  background: var(--bg-elevated);
  color: var(--text);
  transition: border-color 0.12s ease, box-shadow 0.12s ease;
}

input:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px var(--primary-weak);
}

.activity-form__error {
  margin: 0;
  color: var(--danger);
  font-size: 13px;
  font-weight: 500;
}

/* ---------------------------------------------------------------------------
 * Activity list
 *---------------------------------------------------------------------------- */

.activity-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.activity {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 14px;
  box-shadow: var(--shadow-sm);
}

.activity__check {
  display: inline-grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 8px;
  border: 2px solid var(--border-strong);
  background: var(--bg-elevated);
  color: #fff;
  cursor: pointer;
  flex-shrink: 0;
  transition: background-color 0.12s ease, border-color 0.12s ease, color 0.12s ease;
}

.activity__check:hover {
  border-color: var(--primary);
}

.activity__check.is-done {
  background: var(--success);
  border-color: var(--success);
}

.activity__check:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.activity__main {
  flex: 1;
  min-width: 0;
}

.activity__name {
  font-weight: 600;
  font-size: 15px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.activity[data-completed='true'] .activity__name {
  text-decoration: line-through;
  color: var(--text-muted);
}

.activity__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
  margin-top: 3px;
}

.activity__desc {
  color: var(--text-muted);
  font-size: 13px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.badge {
  font-size: 11px;
  font-weight: 600;
  padding: 3px 8px;
  border-radius: 999px;
  background: var(--primary-weak);
  color: var(--primary);
  white-space: nowrap;
}

.activity__counter {
  display: flex;
  align-items: center;
}

.activity__target {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
}

.activity__actions {
  display: flex;
  gap: 6px;
}

/* ---------------------------------------------------------------------------
 * Empty state
 *---------------------------------------------------------------------------- */

.empty-state {
  text-align: center;
  padding: 48px 24px;
  background: var(--surface);
  border: 1px dashed var(--border-strong);
  border-radius: var(--radius-lg);
  color: var(--text-muted);
}

.empty-state__icon {
  display: inline-grid;
  place-items: center;
  width: 64px;
  height: 64px;
  margin: 0 auto 16px;
  border-radius: 18px;
  background: var(--surface-alt);
  color: var(--text-muted);
}

.empty-state__title {
  color: var(--text);
  font-size: 18px;
  margin-bottom: 6px;
}

.empty-state__desc {
  font-size: 14px;
  max-width: 40ch;
  margin: 0 auto 18px;
}

.empty-state__action {
  display: flex;
  justify-content: center;
}

/* ---------------------------------------------------------------------------
 * Dialog (edit)
 *---------------------------------------------------------------------------- */

.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.5);
  display: grid;
  place-items: center;
  padding: 16px;
  z-index: 50;
  animation: fade 0.12s ease;
}

@keyframes fade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.dialog {
  width: 100%;
  max-width: 440px;
  background: var(--bg-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-md);
  animation: pop 0.14s ease;
}

@keyframes pop {
  from {
    transform: translateY(8px) scale(0.98);
    opacity: 0;
  }
  to {
    transform: none;
    opacity: 1;
  }
}

.dialog__title {
  font-size: 17px;
  margin-bottom: 14px;
}

/* ---------------------------------------------------------------------------
 * Toasts
 *---------------------------------------------------------------------------- */

.toasts {
  position: fixed;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  gap: 8px;
  z-index: 60;
  width: calc(100% - 32px);
  max-width: 380px;
}

.toast {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  padding: 12px 14px;
  font-size: 14px;
  cursor: pointer;
  box-shadow: var(--shadow-md);
  color: var(--text);
  background: var(--surface);
  border-color: var(--border);
}

.toast--success {
  background: var(--success-weak);
  border-color: var(--success);
  color: var(--success);
}

.toast--error {
  background: var(--danger-weak);
  border-color: var(--danger);
  color: var(--danger);
}

.toast__close {
  font-size: 18px;
  line-height: 1;
  opacity: 0.7;
}

/* ---------------------------------------------------------------------------
 * Hint
 *---------------------------------------------------------------------------- */

.hint {
  margin: 0;
  font-size: 13px;
  color: var(--warning);
  background: var(--warning);
  color: #fff;
  padding: 10px 14px;
  border-radius: var(--radius-sm);
}

/* ---------------------------------------------------------------------------
 * Responsive
 *---------------------------------------------------------------------------- */

@media (max-width: 480px) {
  .activity-form__row {
    grid-template-columns: 1fr;
  }

  .dashboard__stats {
    grid-template-columns: repeat(3, 1fr);
    gap: 8px;
  }

  .stat {
    padding: 10px 6px;
  }

  .stat__value {
    font-size: 22px;
  }

  .day-nav__label {
    font-size: 15px;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
  }
}

input.newString:
.hint {
  margin: 0;
  font-size: 13px;
  font-weight: 500;
  color: #fff;
  background: var(--warning);
  padding: 10px 14px;
  border-radius: var(--radius-sm);
}

input.oldString:
.hint {
  margin: 0;
  font-size: 13px;
  color: var(--warning);
  background: var(--warning);
  color: #fff;
  padding: 10px 14px;
