import { describe, expect, it } from 'vitest'
import {
  clearStored,
  parseStored,
  readStored,
  StorageBackend,
  validateActivity,
  writeStored,
} from './storage'
import { STORAGE_KEY, STORAGE_VERSION, type StorageData } from '../types'

function memoryBackend(initial: Record<string, string> = {}): StorageBackend & { raw: string | null } {
  const raw: Record<string, string> = { ...initial }
  return {
    raw: null,
    get: (k) => (k in raw ? raw[k] : null),
    set: (k, v) => {
      raw[k] = v
    },
    remove: (k) => {
      delete raw[k]
    },
  } as unknown as StorageBackend & { raw: string | null }
}

const baseData: StorageData = {
  version: STORAGE_VERSION,
  activities: {
    a1: {
      id: 'a1',
      name: 'Sport',
      description: 'Im Fitnessstudio',
      category: 'Gesundheit',
      dailyTarget: 1,
      createdAt: '2026-01-01T08:00:00.000Z',
    },
  },
  completions: { '2026-01-01': { a1: 1 } },
}

describe('parseStored — Validierung & Migration', () => {
  it('liefert einen leeren Ausgangszustand bei leerem Speicher', () => {
    const data = parseStored(null)
    expect(data).not.toBeNull()
    expect(data!.activities).toEqual({})
    expect(data!.version).toBe(STORAGE_VERSION)
  })

  it('akzeptiert gültige v1-Daten', () => {
    const data = parseStored(JSON.stringify(baseData))
    expect(data).not.toBeNull()
    expect(data!.activities.a1.name).toBe('Sport')
    expect(data!.completions['2026-01-01'].a1).toBe(1)
  })

  it('migriert v0 (Array-basierte) Daten in v1', () => {
    const legacy = {
      version: 0,
      activities: [
        {
          id: 'x1',
          name: 'Lesen',
          description: '',
          category: 'Zeit',
          dailyTarget: 2,
          createdAt: '2026-01-02T08:00:00.000Z',
        },
      ],
      completions: [{ date: '2026-01-02', activityId: 'x1', count: 1 }],
    }
    const data = parseStored(JSON.stringify(legacy))
    expect(data).not.toBeNull()
    expect(data!.version).toBe(STORAGE_VERSION)
    expect(data!.activities.x1).toBeDefined()
    expect(data!.completions['2026-01-02'].x1).toBe(1)
  })

  it('ignoriert ungültige Aktivitäts-Einträge, statt zu abstürzen', () => {
    const messy = {
      version: 1,
      activities: {
        good: baseData.activities.a1,
        bad: { id: 'bad', name: 42 },
        alsoBad: 'nope',
      },
      completions: {},
    }
    const data = parseStored(JSON.stringify(messy))
    expect(data!.activities.good).toBeDefined()
    expect(data!.activities.bad).toBeUndefined()
    expect(data!.activities.alsoBad).toBeUndefined()
  })

  it('behandelt beschädigtes JSON sicher als leer (null -> Reset)', () => {
    expect(parseStored('{not valid json')).toBeNull()
    expect(parseStored('123')).toBeNull()
    expect(parseStored('"eine Zeichenkette"')).toBeNull()
    expect(parseStored('[1,2,3]')).toBeNull()
    expect(parseStored(JSON.stringify({ version: 999 }))).toBeNull()
  })
})

describe('readStored / writeStored — Persistenz', () => {
  it('schreibt und liest über ein Backend', () => {
    const backend = memoryBackend()
    writeStored(baseData, backend)
    const read = readStored(backend)
    expect(read.activities.a1.name).toBe('Sport')
  })

  it('schreibt unter dem Storage-Schlüssel', () => {
    const backend = memoryBackend()
    writeStored(baseData, backend)
    expect(backend.raw).toBe(JSON.stringify(baseData))
  })

  it('readStored liefert bei fehlendem Schlüssel einen leeren Zustand', () => {
    const backend = memoryBackend()
    expect(readStored(backend).activities).toEqual({})
  })

  it('clearStored entfernt die Daten', () => {
    const backend = memoryBackend()
    writeStored(baseData, backend)
    clearStored(backend)
    expect(backend.get(STORAGE_KEY)).toBeNull()
  })
})

describe('validateActivity', () => {
  it('akzeptiert gültige Eingaben', () => {
    const res = validateActivity(
      { name: '  Wasser trinken  ', description: '2L', category: 'Gesundheit', dailyTarget: 3 },
      {},
    )
    expect(res.ok).toBe(true)
    if (res.ok) {
      expect(res.activity.name).toBe('Wasser trinken')
      expect(res.activity.category).toBe('Gesundheit')
      expect(res.activity.dailyTarget).toBe(3)
      expect(res.activity.id).toBeTruthy()
    }
  })

  it('lehnt leeren Name ab', () => {
    const res = validateActivity({ name: '   ', category: 'x' }, {})
    expect(res.ok).toBe(false)
    if (!res.ok) expect(res.error).toMatch(/Name/)
  })

  it('lehnt leere Kategorie ab', () => {
    const res = validateActivity({ name: 'x', category: '' }, {})
    expect(res.ok).toBe(false)
  })

  it('lehnt negatives Tagesziel ab', () => {
    const res = validateActivity({ name: 'x', category: 'y', dailyTarget: -2 }, {})
    expect(res.ok).toBe(false)
  })

  it('roundet ein deziminales Ziel auf eine ganze Zahl', () => {
    const res = validateActivity({ name: 'x', category: 'y', dailyTarget: 2.9 }, {})
    expect(res.ok).toBe(true)
    if (res.ok) expect(res.activity.dailyTarget).toBe(2)
  })
})

import { describe, expect, it } from 'vitest'
import { addDays, dateToKey, keyToDate, formatDayLabel, isFuture, isToday, todayKey } from './date'

describe('date helpers', () => {
  it('formattelt lokale Datums in YYYY-MM-DD', () => {
    expect(dateToKey(new Date(2026, 0, 5))).toBe('2026-01-05')
    expect(dateToKey(new Date(2026, 11, 31))).toBe('2026-12-31')
  })

  it('wandelt Ketten zurück in Dates', () => {
    const d = keyToDate('2026-01-05')
    expect(d.getFullYear()).toBe(2026)
    expect(d.getMonth()).toBe(0)
    expect(d.getDate()).toBe(5)
  })

  it('addiert und subtrahiert Tage', () => {
    expect(addDays('2026-01-05', 1)).toBe('2026-01-06')
    expect(addDays('2026-01-05', -1)).toBe('2026-01-04')
    expect(addDays('2026-01-01', 30)).toBe('2026-01-31')
  })

  it('erkennt Zukunft und heute', () => {
    const today = '2026-09-24'
    expect(isFuture('2026-09-25', today)).toBe(true)
    expect(isFuture('2026-09-23', today)).toBe(false)
    expect(isFuture('2026-09-24', today)).toBe(false)
    expect(isToday('2026-09-24', today)).toBe(true)
    expect(isToday('2026-09-25', today)).toBe(false)
  })

  it('liefert relative Labels', () => {
    const today = '2026-09-24'
    expect(formatDayLabel('2026-09-24', today)).toBe('Heute')
    expect(formatDayLabel('2026-09-23', today)).toBe('Gestern')
    expect(formatDayLabel('2026-09-25', today)).toBe('Morgen')
    expect(formatDayLabel('2026-09-28', today)).toMatch(/September/)
  })

  it('todayKey nutzt das übergebene Datum', () => {
    expect(todayKey(new Date(2026, 8, 24))).toBe('2026-09-24')
  })
})

import { describe, expect, it } from 'vitest'
import {
  computeStats,
  createStore,
  getCompletedCount,
  isCompleted,
  listCategories,
  type Store,
} from './createStore'
import { StorageBackend, type StorageData } from './storage'
import type { Activity } from '../types'

function memoryBackend(initial: Record<string, string> = {}): StorageBackend {
  const raw: Record<string, string> = { ...initial }
  const backend: StorageBackend = {
    get: (k) => (k in raw ? raw[k] : null),
    set: (k, v) => {
      raw[k] = v
    },
    remove: (k) => {
      delete raw[k]
    },
  }
  return backend
}

const FIXED_NOW = new Date(2026, 8, 24, 10, 0, 0) // 2026-09-24
const today = '2026-09-24'
const yesterday = '2026-09-23'
const tomorrow = '2026-09-25'

function makeStore(backend?: StorageBackend, now: Date = FIXED_NOW): Store {
  return createStore({ backend, now: () => now })
}

function sampleActivity(overrides: Partial<Activity> = {}): Activity {
  return {
    id: 'a1',
    name: 'Sport',
    description: 'Fitness',
    category: 'Gesundheit',
    dailyTarget: 1,
    createdAt: '2026-09-01T08:00:00.000Z',
    ...overrides,
  }
}

describe('store — Aktivitäten verwalten', () => {
  it('erstellt eine Aktivität', () => {
    const store = makeStore()
    const activity = store.addActivity({ name: 'Lesen', category: 'Zeit', dailyTarget: 2 })
    expect(activity).not.toBeNull()
    expect(store.getState().data.activities[activity!.id].name).toBe('Lesen')
    expect(store.getState().data.activities[activity!.id].dailyTarget).toBe(2)
  })

  it('lehnt das Anlegen einer ungültigen Aktivität ab', () => {
    const store = makeStore()
    expect(store.addActivity({ name: '  ', category: 'x' })).toBeNull()
    expect(store.getState().data.activities).toEqual({})
  })

  it('bearbeitet eine Aktivität', () => {
    const store = makeStore()
    const a = store.addActivity({ name: 'Sport', category: 'G' })!
    const ok = store.editActivity(a.id, { name: 'Fitness', category: 'Gesundheit', dailyTarget: 3 })
    expect(ok).toBe(true)
    expect(store.getState().data.activities[a.id].name).toBe('Fitness')
    expect(store.getState().data.activities[a.id].dailyTarget).toBe(3)
  })

  it('lehnt das Bearbeiten einer unbekannten ID ab', () => {
    const store = makeStore()
    expect(store.editActivity('nope', { name: 'x', category: 'y' })).toBe(false)
  })

  it('löscht eine Aktivität und deren veraltete Zählstände', () => {
    const store = makeStore()
    const a = store.addActivity({ name: 'Sport', category: 'G' })!
    store.toggleComplete(a.id, today)
    expect(getCompletedCount(store.getState().data, a.id, today)).toBe(1)
    store.deleteActivity(a.id)
    expect(store.getState().data.activities[a.id]).toBeUndefined()
    // Verwaigter Zählstand wurde entfernt.
    const anyDate = Object.keys(store.getState().data.completions)[0]
    expect(anyDate).toBeUndefined()
  })
})

describe('store — Tagesstatus', () => {
  it('schaltet einen Eintrag ohne Ziel ein/aus', () => {
    const store = makeStore()
    const a = store.addActivity({ name: 'Wasser', category: 'G', dailyTarget: 0 })!
    store.toggleComplete(a.id, today)
    expect(getCompletedCount(store.getState().data, a.id, today)).toBe(1)
    expect(isCompleted(store.getState().data, a, today)).toBe(true)
    store.toggleComplete(a.id, today)
    expect(getCompletedCount(store.getState().data, a.id, today)).toBe(0)
  })

  it('zählt ein Tagesziel hoch und runter', () => {
    const store = makeStore()
    const a = store.addActivity({ name: 'Lesen', category: 'Z', dailyTarget: 3 })!
    store.toggleComplete(a.id, today)
    store.toggleComplete(a.id, today)
    expect(getCompletedCount(store.getState().data, a.id, today)).toBe(2)
    expect(isCompleted(store.getState().data, a, today)).toBe(false)
    store.toggleComplete(a.id, today)
    expect(isCompleted(store.getState().data, a, today)).toBe(true)
    store.toggleComplete(a.id, today)
    expect(getCompletedCount(store.getState().data, a.id, today)).toBe(2)
  })

  it('überschreibt verschiedene Kalendertage nicht', () => {
    const store = makeStore()
    const a = store.addActivity({ name: 'Sport', category: 'G', dailyTarget: 1 })!
    store.toggleComplete(a.id, today)
    expect(getCompletedCount(store.getState().data, a.id, today)).toBe(1)
    expect(getCompletedCount(store.getState().data, a.id, yesterday)).toBe(0)
  })

  it('markiert zukünftige Tage nicht als erledigt', () => {
    const store = makeStore()
    const a = store.addActivity({ name: 'Sport', category: 'G' })!
    store.toggleComplete(a.id, tomorrow)
    expect(getCompletedCount(store.getState().data, a.id, tomorrow)).toBe(0)
  })

  it('merkt sich den Status über Subscriber-Ankündigungen', () => {
    const store = makeStore()
    const a = store.addActivity({ name: 'Sport', category: 'G' })!
    let updates = 0
    store.subscribe(() => {
      updates++
    })
    store.toggleComplete(a.id, today)
    expect(updates).toBe(1)
  })
})

describe('store — Datumswechsel', () => {
  it('wählt einen Tag aus', () => {
    const store = makeStore()
    store.setSelectedDate(yesterday)
    expect(store.getState().selectedDate).toBe(yesterday)
  })
})

describe('store — Persistenz & Wiederherstellung', () => {
  it('wiederholt Daten über ein geteiltes Backend (Reload-Simulation)', () => {
    const backend = memoryBackend()
    const store1 = makeStore(backend)
    const a = store1.addActivity({ name: 'Sport', category: 'G', dailyTarget: 2 })!
    store1.toggleComplete(a.id, today)

    // Neue Instanz, gleicher Storage -> Daten müssen vorhanden sein.
    const store2 = makeStore(backend)
    expect(store2.getState().data.activities[a.id]).toBeDefined()
    expect(getCompletedCount(store2.getState().data, a.id, today)).toBe(1)
  })

  it('erholt sich von beschädigten gespeicherten Daten', () => {
    const backend = memoryBackend({
      pulseboard: '{ this ist beschädigt }',
    })
    const store = makeStore(backend)
    // Kein Absturz, leerer Zustand.
    expect(store.getState().data.activities).toEqual({})
    // Nach dem Laden wird ein sauberer Zustand zurückschrieben.
    store.reload()
    expect(typeof store.getState().data.version).toBe('number')
  })

  it('reset löscht alle Daten', () => {
    const backend = memoryBackend()
    const store = makeStore(backend)
    store.addActivity({ name: 'Sport', category: 'G' })
    expect(Object.keys(store.getState().data.activities).length).toBe(1)
    store.reset()
    expect(Object.keys(store.getState().data.activities).length).toBe(0)
  })
})

describe('computeStats / listCategories', () => {
  function populatedStore(): { store: Store; sport: Activity; read: Activity } {
    const store = makeStore()
    const sport = store.addActivity({ name: 'Sport', category: 'Gesundheit', dailyTarget: 1 })!
    const read = store.addActivity({ name: 'Lesen', category: 'Zeit', dailyTarget: 0 })!
    store.toggleComplete(sport.id, today)
    return { store, sport, read }
  }

  it('berechnet erledigt/offen/Prozent', () => {
    const { store } = populatedStore()
    const stats = computeStats(store.getState().data, today)
    expect(stats.total).toBe(2)
    expect(stats.completed).toBe(1)
    expect(stats.open).toBe(1)
    expect(stats.percent).toBe(50)
  })

  it('ordnet Kategorien zu', () => {
    const { store } = populatedStore()
    const stats = computeStats(store.getState().data, today)
    expect(stats.byCategory).toEqual([
      { name: 'Gesundheit', total: 1, completed: 1 },
      { name: 'Zeit', total: 1, completed: 0 },
    ])
  })

  it('listCategories liefert sortierte, eindeutige Namen', () => {
    const { store } = populatedStore()
    expect(listCategories(store.getState().data)).toEqual(['Gesundheit', 'Zeit'])
  })

  it('zeigt 0 % bei fehlenden Aktivitäten', () => {
    const store = makeStore()
    const stats = computeStats(store.getState().data, today)
    expect(stats.completed).toBe(0)
    expect(stats.percent).toBe(0)
  })
})

import { describe, expect, it } from 'vitest'
import { renderHook, act } from '@testing-library/react'
import { useAppStore } from '../hooks/useAppStore'
import { getCompletedCount } from '../store/createStore'
import { STORAGE_KEY } from '../types'

describe('useAppStore (React-Integration, localStorage)', () => {
  it('startet mit einem leeren Zustand', () => {
    const { result } = renderHook(() => useAppStore())
    expect(result.getState().data.activities).toEqual({})
  })

  it('erstellt, bearbeitet und löscht über den Hook', () => {
    const { result } = renderHook(() => useAppStore())

    act(() => {
      result.addActivity({ name: 'Sport', category: 'G', dailyTarget: 1 })
    })
    expect(Object.keys(result.getState().data.activities).length).toBe(1)

    const id = Object.keys(result.getState().data.activities)[0]
    act(() => {
      result.editActivity(id, { name: 'Fitness', category: 'Gesundheit', dailyTarget: 2 })
    })
    expect(result.getState().data.activities[id].name).toBe('Fitness')

    act(() => {
      result.deleteActivity(id)
    })
    expect(result.getState().data.activities[id]).toBeUndefined()
  })

  it('speichert den Tagesstatus und überlebt einen Reload', () => {
    const { result, rerender } = renderHook(() => useAppStore())
    const date = result.getState().selectedDate

    act(() => {
      result.addActivity({ name: 'Wasser', category: 'G', dailyTarget: 0 })
    })
    const id = Object.keys(result.getState().data.activities)[0]

    act(() => {
      result.toggleComplete(id, date)
    })
    expect(getCompletedCount(result.getState().data, id, date)).toBe(1)

    // Reload: neuer Hook-Lesevorgang aus dem gleichen localStorage.
    rerender()
    expect(getCompletedCount(result.getState().data, id, date)).toBe(1)
  })

  it('erholt sich von beschädigten localStorage-Daten', () => {
    localStorage.setItem(STORAGE_KEY, '{ corrupt data')
    const { result } = renderHook(() => useAppStore())
    expect(result.getState().data.activities).toEqual({})
  })

  it('wählt einen Tag aus', () => {
    const { result } = renderHook(() => useAppStore())
    act(() => {
      result.setSelectedDate('2026-01-15')
    })
    expect(result.getState().selectedDate).toBe('2026-01-15')
  })
})

